public sealed class DomainExceptionHandler(ILogger<DomainExceptionHandler> log, IProblemDetailsService pds) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext ctx, Exception ex, CancellationToken ct)
    {
        var (status, title) = ex switch
        {
            ValidationException => (400, "Validation failed"),
            NotFoundException   => (404, "Not found"),
            StudyLockedException => (409, "Study is locked"),
            _ => (500, "Unexpected error")
        };
        if (status == 500) log.LogError(ex, "Unhandled exception");
        ctx.Response.StatusCode = status;
        return await pds.TryWriteAsync(new() { HttpContext = ctx,
            ProblemDetails = { Title = title, Status = status, Extensions = { ["traceId"] = ctx.TraceIdentifier } } });
    }
}

